import{_ as i,C as r,o,c as l,j as n,a as t,E as d,a2 as s}from"./chunks/framework.CtQGab4e.js";const v=JSON.parse('{"title":"Veelgestelde vragen","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),p={name:"faq.md"};function g(h,e,u,m,k,b){const a=r("Icon");return o(),l("div",null,[e[5]||(e[5]=n("h1",{id:"veelgestelde-vragen",tabindex:"-1"},[t("Veelgestelde vragen "),n("a",{class:"header-anchor",href:"#veelgestelde-vragen","aria-label":'Permalink to "Veelgestelde vragen"'},"​")],-1)),e[6]||(e[6]=n("h2",{id:"ik-tik-in-een-ruimte-maar-er-opent-geen-popup",tabindex:"-1"},[t("Ik tik in een ruimte, maar er opent geen popup "),n("a",{class:"header-anchor",href:"#ik-tik-in-een-ruimte-maar-er-opent-geen-popup","aria-label":'Permalink to "Ik tik in een ruimte, maar er opent geen popup"'},"​")],-1)),n("ul",null,[n("li",null,[e[0]||(e[0]=t("Gebruik je de ",-1)),d(a,{name:"wall"}),e[1]||(e[1]=t()),e[2]||(e[2]=n("strong",null,"Muur",-1)),e[3]||(e[3]=t("-tool? De vlak-popup opent alleen met die tool.",-1))]),e[4]||(e[4]=n("li",null,"Is de ring van muren dicht? Zit er ergens een kier, of eindigt een muur net naast een hoekpunt in plaats van erop, dan is er geen vlak. Sleep het losse uiteinde op het hoekpunt tot het vastklikt.",-1))]),e[7]||(e[7]=s('<h2 id="een-verdieping-ontbreekt-in-3d" tabindex="-1">Een verdieping ontbreekt in 3D <a class="header-anchor" href="#een-verdieping-ontbreekt-in-3d" aria-label="Permalink to &quot;Een verdieping ontbreekt in 3D&quot;">​</a></h2><p>In het log staat <em>&quot;Geen referentiepunt, overgeslagen&quot;</em>: die verdieping heeft een hoogte, maar geen gekoppelde hoek. Koppel er een, zie <a href="./plattegrond/gebouw.html#referentiepunten">Referentiepunten</a>.</p><h2 id="mijn-verdiepingen-liggen-in-3d-niet-goed-op-elkaar" tabindex="-1">Mijn verdiepingen liggen in 3D niet goed op elkaar <a class="header-anchor" href="#mijn-verdiepingen-liggen-in-3d-niet-goed-op-elkaar" aria-label="Permalink to &quot;Mijn verdiepingen liggen in 3D niet goed op elkaar&quot;">​</a></h2><p>Koppel op elke verdieping <strong>dezelfde hoek van het gebouw</strong>. Met het oogje bij <a href="./plattegrond/gebouw.html#referentiepunten">Referentiepunten</a> zie je welke hoeken gekoppeld zijn.</p><h2 id="er-zit-een-spleet-of-een-smal-randje-tussen-mijn-verdiepingen-in-3d" tabindex="-1">Er zit een spleet of een smal randje tussen mijn verdiepingen in 3D <a class="header-anchor" href="#er-zit-een-spleet-of-een-smal-randje-tussen-mijn-verdiepingen-in-3d" aria-label="Permalink to &quot;Er zit een spleet of een smal randje tussen mijn verdiepingen in 3D&quot;">​</a></h2><p>Dat komt door binnenwerks meten: elke verdieping is een paar cm anders. Zie <a href="./hoe-teken-ik/twee-lagen.html#is-een-verdieping-een-paar-cm-kleiner-of-groter-dan-die-eronder">Is een verdieping een paar cm kleiner of groter</a>.</p><h2 id="een-aanbouw-heeft-een-lager-plat-dak-moet-dat-een-gebouwdeel-worden" tabindex="-1">Een aanbouw heeft een lager plat dak. Moet dat een gebouwdeel worden? <a class="header-anchor" href="#een-aanbouw-heeft-een-lager-plat-dak-moet-dat-een-gebouwdeel-worden" aria-label="Permalink to &quot;Een aanbouw heeft een lager plat dak. Moet dat een gebouwdeel worden?&quot;">​</a></h2><p>Dat hoeft niet: met het hoogteveld bij het platte dak krijg je hetzelfde 3D-model, zie <a href="./hoe-teken-ik/lagere-aanbouw.html">Lagere aanbouw met plat dak</a>. Het verschil zit in de uitkomst: als gebouwdeel krijgt de aanbouw eigen constructies, anders tellen de m² mee bij het hoofdhuis. Zie <a href="./hoe-teken-ik/aanbouw.html">Aanbouw met eigen hoogtes</a>.</p><h2 id="genereer-is-grijs" tabindex="-1">Genereer is grijs <a class="header-anchor" href="#genereer-is-grijs" aria-label="Permalink to &quot;Genereer is grijs&quot;">​</a></h2><ul><li>Staat er <em>Vul eerst je 3D-sleutel in bij Instellingen</em>? Dan ontbreekt je <a href="./plattegrond/3d-paneel.html#aanzetten">3D-sleutel</a>.</li><li>Staat er <em>Verbinden met de 3D-server…</em>? Wacht een paar seconden.</li><li>Staat er een rode melding? Zie <a href="./plattegrond/3d-paneel.html#als-er-iets-misgaat">Als er iets misgaat</a>.</li></ul><h2 id="mijn-correcties-zijn-weg" tabindex="-1">Mijn correcties zijn weg <a class="header-anchor" href="#mijn-correcties-zijn-weg" aria-label="Permalink to &quot;Mijn correcties zijn weg&quot;">​</a></h2><p>Je hebt opnieuw gegenereerd: bij een nieuw model vervallen de correcties. Corrigeer pas als de tekening af is. Zie <a href="./plattegrond/3d-paneel.html#genereren">Genereren</a>.</p><h2 id="er-staat-de-tekening-is-gewijzigd-na-het-genereren" tabindex="-1">Er staat &quot;De tekening is gewijzigd na het genereren&quot; <a class="header-anchor" href="#er-staat-de-tekening-is-gewijzigd-na-het-genereren" aria-label="Permalink to &quot;Er staat &quot;De tekening is gewijzigd na het genereren&quot;&quot;">​</a></h2><p>Het 3D-model hoort bij een eerdere versie van je tekening; ook een verschoven hoekpunt telt. Tik op <strong>Genereer</strong> voor een nieuw model.</p><h2 id="er-komt-geen-label-wise-bestand-uit-de-export" tabindex="-1">Er komt geen Label-wise-bestand uit de export <a class="header-anchor" href="#er-komt-geen-label-wise-bestand-uit-de-export" aria-label="Permalink to &quot;Er komt geen Label-wise-bestand uit de export&quot;">​</a></h2><p>Er zijn kozijnen die nog gekoppeld moeten worden, of er is geen enkel kozijn gekoppeld. Tik op <strong>Naar Kozijnen</strong>, zie <a href="./plattegrond/kozijnen-koppelen.html#klaar">Kozijnen koppelen</a>.</p><h2 id="bij-een-kozijn-staat-constructie-bestaat-niet-meer" tabindex="-1">Bij een kozijn staat &quot;constructie bestaat niet meer&quot; <a class="header-anchor" href="#bij-een-kozijn-staat-constructie-bestaat-niet-meer" aria-label="Permalink to &quot;Bij een kozijn staat &quot;constructie bestaat niet meer&quot;&quot;">​</a></h2><p>De constructie is na het koppelen veranderd of verwijderd. Koppel het kozijn opnieuw, zie <a href="./plattegrond/kozijnen-koppelen.html#opnieuw-genereren">Opnieuw genereren</a>.</p><h2 id="de-interactieve-weergave-doet-niets-op-de-ipad" tabindex="-1">De interactieve weergave doet niets op de iPad <a class="header-anchor" href="#de-interactieve-weergave-doet-niets-op-de-ipad" aria-label="Permalink to &quot;De interactieve weergave doet niets op de iPad&quot;">​</a></h2><p>Daar draait hij niet: open het bestand op een computer. Zie <a href="./plattegrond/export-3d.html#uit-het-3d-paneel">Exporteren voor 3D</a>.</p><h2 id="ik-zie-een-voorbeeld-maar-het-staat-niet-bij-mijn-projecten" tabindex="-1">Ik zie een voorbeeld, maar het staat niet bij mijn projecten <a class="header-anchor" href="#ik-zie-een-voorbeeld-maar-het-staat-niet-bij-mijn-projecten" aria-label="Permalink to &quot;Ik zie een voorbeeld, maar het staat niet bij mijn projecten&quot;">​</a></h2><p>Een voorbeeld uit de handleiding wordt niet bewaard, tenzij je in de balk bovenin op <strong>Bewaren als notitie</strong> tikt.</p>',22))])}const f=i(p,[["render",g]]);export{v as __pageData,f as default};
